Object.assign(SNIP,{});PRESET_NOTES["l25"]={"Ví dụ: Dựng danh sách và duyệt": "Mỗi lần thêm vào đầu, nút mới trỏ tới head cũ rồi trở thành head. Thêm 4, 1, 3 thì danh sách là 3 → 1 → 4 (ngược thứ tự thêm). Vòng for thứ hai: cur đi từ head theo mũi tên next tới khi gặp nullptr.", "Ví dụ: Chèn sau một nút và xóa nút": "Chèn: q được nối vào sau p bằng hai phép gán, không phải dời nút nào. Xóa: head->next nhảy qua nút 2, rồi delete trả bộ nhớ của nút đó. Kết quả 1 2 3 4, rồi 1 3 4.", "Ví dụ: Đảo ngược danh sách bằng ba con trỏ": "Hai hàng trong hình: hàng trên là phần đã đảo (bắt đầu từ prev), hàng dưới là phần chưa đảo (từ cur). Mỗi vòng, một nút chuyển từ hàng dưới lên đầu hàng trên. Kết quả 4 3 2 1. O(n) thời gian, O(1) bộ nhớ thêm.", "Ví dụ: Tìm nút giữa bằng con trỏ nhanh, chậm": "nhanh đi gấp đôi cham, nên khi nhanh hết đường thì cham ở giữa: với 7 nút là nút 4. Điều kiện vòng lặp kiểm tra cả nhanh và nhanh->next để không bao giờ đọc ->next của nullptr.", "Lỗi: đọc ->next của con trỏ rỗng": "Với 3 nút: nhanh từ nút 1 nhảy tới nút 3, rồi nhảy hai bước nữa thành nullptr. Vòng lặp kiểm tra nhanh->next khi nhanh đã là nullptr: chương trình bị dừng (Segmentation fault). Luôn kiểm tra con trỏ khác rỗng trước khi dùng ->."};EX_HINTS["l25"]=[["Giữ ba con trỏ: prev (phần đã đảo), cur (nút đang xét), nxt (phần còn lại).", "Trong vòng lặp: nxt = cur->next; cur->next = prev; prev = cur; cur = nxt.", "Khi cur thành nullptr, prev là head mới."], ["Để xóa một nút cần con trỏ p tới nút đứng trước nó, rồi p->next = p->next->next.", "Nút giả gia(0, head) đứng trước head: nhờ nó, xóa nút đầu không cần trường hợp riêng. Kết quả là gia.next.", "Khi vừa xóa p->next thì đừng tiến p: nút mới đứng sau p có thể cũng phải xóa."], ["Thuật toán Floyd: cham đi 1 bước, nhanh đi 2 bước. Nhanh gặp nullptr thì không có chu trình; cham == nhanh thì có.", "Khi đã gặp nhau, cả hai đang ở trong chu trình: giữ cham đứng yên, cho một con trỏ đi vòng tới khi quay lại cham, đếm số bước.", "So sánh hai con trỏ (cham == nhanh) là so sánh địa chỉ nút, không phải giá trị val: các nút khác nhau có thể cùng giá trị."]];
/* ===================== BÀI 25 · Danh sách liên kết ===================== */
/* Bài 25 · Danh sách liên kết
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR25=[{label:"Ví dụ: Dựng danh sách và duyệt",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* next;\n    Node(int v, Node* n) : val(v), next(n) {}\n};\n\nint main() {\n    int a[3] = {4, 1, 3};\n    Node* head = nullptr;\n    for (int i = 0; i < 3; i++) {\n        head = new Node(a[i], head);   // thêm vào đầu\n    }\n    for (Node* cur = head; cur != nullptr; cur = cur->next) {\n        cout << cur->val << \" \";\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"links",of:"head",ptr:["cur"]}],py:{code:"class Node:\n    def __init__(self, val, next=None):\n        self.val = val\n        self.next = next\n\nhead = None\nfor x in [4, 1, 3]:\n    head = Node(x, head)      # thêm vào đầu\n\ncur = head\nwhile cur is not None:\n    print(cur.val, end=\" \")\n    cur = cur.next\nprint()"},cs:{code:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Next;\n\n    public Node(int val, Node next)\n    {\n        Val = val;\n        Next = next;\n    }\n}\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 4, 1, 3 };\n        Node head = null;\n        for (int i = 0; i < 3; i++)\n        {\n            head = new Node(a[i], head);   // thêm vào đầu\n        }\n        for (Node cur = head; cur != null; cur = cur.Next)\n        {\n            Console.Write(cur.Val + \" \");\n        }\n        Console.WriteLine();\n    }\n}",viz:[{type:"links",next:"Next",val:"Val",of:"head",ptr:["cur"]}]}},{label:"Ví dụ: Chèn sau một nút và xóa nút",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* next;\n    Node(int v, Node* n) : val(v), next(n) {}\n};\n\nvoid inDS(Node* head) {\n    for (Node* c = head; c != nullptr; c = c->next) cout << c->val << \" \";\n    cout << \"\\n\";\n}\n\nint main() {\n    Node* head = new Node(1, new Node(2, new Node(4, nullptr)));\n    Node* p = head->next;               // p trỏ tới nút 2\n    Node* q = new Node(3, p->next);     // bước 1: q trỏ tới nút sau p\n    p->next = q;                        // bước 2: p trỏ tới q\n    inDS(head);\n    Node* bo = head->next;              // xóa nút đứng sau head (nút 2)\n    head->next = bo->next;              // nối tắt qua nút bị xóa\n    delete bo;\n    inDS(head);\n    return 0;\n}",viz:[{type:"links",of:"head",ptr:["p","q","bo"]}],py:{code:"class Node:\n    def __init__(self, val, next=None):\n        self.val = val\n        self.next = next\n\ndef inDS(head):\n    c = head\n    while c is not None:\n        print(c.val, end=\" \")\n        c = c.next\n    print()\n\nhead = Node(1, Node(2, Node(4)))\np = head.next               # p trỏ tới nút 2\nq = Node(3, p.next)         # bước 1: q trỏ tới nút sau p\np.next = q                  # bước 2: p trỏ tới q\ninDS(head)\nbo = head.next              # xóa nút đứng sau head (nút 2)\nhead.next = bo.next         # nối tắt qua nút bị xóa\ninDS(head)",note:"Chèn: q được nối vào sau p bằng hai phép gán. Xóa: head.next nhảy qua nút 2; nút đó không còn nằm trong danh sách (biến bo vẫn trỏ tới nó nên hình còn vẽ, khi bo mất thì Python tự thu hồi). Kết quả 1 2 3 4, rồi 1 3 4."},cs:{code:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Next;\n\n    public Node(int val, Node next)\n    {\n        Val = val;\n        Next = next;\n    }\n}\n\nclass Program\n{\n    static void InDS(Node head)\n    {\n        for (Node c = head; c != null; c = c.Next) Console.Write(c.Val + \" \");\n        Console.WriteLine();\n    }\n\n    static void Main()\n    {\n        Node head = new Node(1, new Node(2, new Node(4, null)));\n        Node p = head.Next;               // p trỏ tới nút 2\n        Node q = new Node(3, p.Next);     // bước 1: q trỏ tới nút sau p\n        p.Next = q;                       // bước 2: p trỏ tới q\n        InDS(head);\n        Node bo = head.Next;              // xóa nút đứng sau head (nút 2)\n        head.Next = bo.Next;              // nối tắt qua nút bị xóa\n        InDS(head);\n    }\n}",viz:[{type:"links",next:"Next",val:"Val",of:"head",ptr:["p","q","bo"]}],note:"Chèn: q được nối vào sau p bằng hai phép gán. Xóa: head.Next nhảy qua nút 2; nút đó không còn nằm trong danh sách, bộ thu gom rác của .NET sẽ thu hồi khi không còn biến nào trỏ tới. Kết quả 1 2 3 4, rồi 1 3 4."}},{label:"Ví dụ: Đảo ngược danh sách bằng ba con trỏ",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* next;\n    Node(int v, Node* n) : val(v), next(n) {}\n};\n\nint main() {\n    Node* head = new Node(1, new Node(2, new Node(3, new Node(4, nullptr))));\n    Node* prev = nullptr;\n    Node* cur = head;\n    while (cur != nullptr) {\n        Node* nxt = cur->next;   // nhớ phần còn lại\n        cur->next = prev;        // bẻ mũi tên quay ngược\n        prev = cur;\n        cur = nxt;\n    }\n    head = prev;\n    for (Node* c = head; c != nullptr; c = c->next) cout << c->val << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"links",of:"prev",ptr:["cur","nxt","head"]}],py:{code:"class Node:\n    def __init__(self, val, next=None):\n        self.val = val\n        self.next = next\n\nhead = Node(1, Node(2, Node(3, Node(4))))\nprev = None\ncur = head\nwhile cur is not None:\n    nxt = cur.next       # nhớ phần còn lại\n    cur.next = prev      # bẻ mũi tên quay ngược\n    prev = cur\n    cur = nxt\nhead = prev\n\nc = head\nwhile c is not None:\n    print(c.val, end=\" \")\n    c = c.next\nprint()"},cs:{code:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Next;\n\n    public Node(int val, Node next)\n    {\n        Val = val;\n        Next = next;\n    }\n}\n\nclass Program\n{\n    static void Main()\n    {\n        Node head = new Node(1, new Node(2, new Node(3, new Node(4, null))));\n        Node prev = null;\n        Node cur = head;\n        while (cur != null)\n        {\n            Node nxt = cur.Next;   // nhớ phần còn lại\n            cur.Next = prev;       // bẻ mũi tên quay ngược\n            prev = cur;\n            cur = nxt;\n        }\n        head = prev;\n        for (Node c = head; c != null; c = c.Next) Console.Write(c.Val + \" \");\n        Console.WriteLine();\n    }\n}",viz:[{type:"links",next:"Next",val:"Val",of:"prev",ptr:["cur","nxt","head"]}]}},{label:"Ví dụ: Tìm nút giữa bằng con trỏ nhanh, chậm",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* next;\n    Node(int v, Node* n) : val(v), next(n) {}\n};\n\nint main() {\n    Node* head = nullptr;\n    for (int x = 7; x >= 1; x--) head = new Node(x, head);   // 1 → 2 → ... → 7\n    Node* cham = head;\n    Node* nhanh = head;\n    while (nhanh != nullptr && nhanh->next != nullptr) {\n        cham = cham->next;            // 1 bước\n        nhanh = nhanh->next->next;    // 2 bước\n    }\n    cout << cham->val << \"\\n\";\n    return 0;\n}",viz:[{type:"links",of:"head",ptr:["cham","nhanh"]}],py:{code:"class Node:\n    def __init__(self, val, next=None):\n        self.val = val\n        self.next = next\n\nhead = None\nfor x in range(7, 0, -1):\n    head = Node(x, head)       # 1 → 2 → ... → 7\n\ncham = nhanh = head\nwhile nhanh is not None and nhanh.next is not None:\n    cham = cham.next           # 1 bước\n    nhanh = nhanh.next.next    # 2 bước\nprint(cham.val)"},cs:{code:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Next;\n\n    public Node(int val, Node next)\n    {\n        Val = val;\n        Next = next;\n    }\n}\n\nclass Program\n{\n    static void Main()\n    {\n        Node head = null;\n        for (int x = 7; x >= 1; x--) head = new Node(x, head);   // 1 → 2 → ... → 7\n        Node cham = head;\n        Node nhanh = head;\n        while (nhanh != null && nhanh.Next != null)\n        {\n            cham = cham.Next;            // 1 bước\n            nhanh = nhanh.Next.Next;     // 2 bước\n        }\n        Console.WriteLine(cham.Val);\n    }\n}",viz:[{type:"links",next:"Next",val:"Val",of:"head",ptr:["cham","nhanh"]}]}},{label:"Lỗi: đọc ->next của con trỏ rỗng",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* next;\n    Node(int v, Node* n) : val(v), next(n) {}\n};\n\nint main() {\n    Node* head = new Node(1, new Node(2, new Node(3, nullptr)));\n    Node* nhanh = head;\n    while (nhanh->next != nullptr) {     // sai: thiếu kiểm tra nhanh != nullptr\n        nhanh = nhanh->next->next;\n    }\n    cout << nhanh->val << \"\\n\";\n    return 0;\n}",viz:[{type:"links",of:"head",ptr:["nhanh"]}],py:{code:"class Node:\n    def __init__(self, val, next=None):\n        self.val = val\n        self.next = next\n\nhead = Node(1, Node(2, Node(3)))\nnhanh = head\nwhile nhanh.next is not None:     # sai: thiếu kiểm tra nhanh is not None\n    nhanh = nhanh.next.next\nprint(nhanh.val)",label:"Lỗi: đọc .next của None",note:"Với 3 nút: nhanh từ nút 1 nhảy tới nút 3, rồi nhảy hai bước nữa thành None. Vòng lặp đọc nhanh.next khi nhanh đã là None: Python báo AttributeError: 'NoneType' object has no attribute 'next'. Luôn kiểm tra is not None trước khi dùng dấu chấm."},cs:{label:"Lỗi: đọc .Next của null",code:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Next;\n\n    public Node(int val, Node next)\n    {\n        Val = val;\n        Next = next;\n    }\n}\n\nclass Program\n{\n    static void Main()\n    {\n        Node head = new Node(1, new Node(2, new Node(3, null)));\n        Node nhanh = head;\n        while (nhanh.Next != null)        // sai: thiếu kiểm tra nhanh != null\n        {\n            nhanh = nhanh.Next.Next;\n        }\n        Console.WriteLine(nhanh.Val);\n    }\n}",viz:[{type:"links",next:"Next",val:"Val",of:"head",ptr:["nhanh"]}],note:"Với 3 nút: nhanh từ nút 1 nhảy tới nút 3, rồi nhảy hai bước nữa thành null. Vòng lặp đọc nhanh.Next khi nhanh đã là null: chương trình dừng với NullReferenceException. Luôn kiểm tra != null trước khi dùng dấu chấm."}}];
const sim25=makeSim2(document.getElementById("sim-l25"),{id:"s25",presets:PR25});
makeEx2(document.getElementById("ex-l25"),sim25,[{t:"Đảo ngược danh sách",d:"Đầu vào: n (1 ≤ n ≤ 10^4) và n số nguyên. Chương trình mẫu đã dựng danh sách liên kết theo đúng thứ tự nhập. Hãy viết hàm daoNguoc đảo ngược danh sách <b>bằng cách đổi các con trỏ next<\/b> (không tạo nút mới, không dùng mảng phụ) và trả về head mới. Đầu ra: danh sách sau khi đảo.",tests:[{in:"4\n1 2 3 4",out:"4 3 2 1"},{in:"1\n7",out:"7"},{in:"2\n5 9",out:"9 5"},{in:"6\n3 3 1 2 2 8",out:"8 2 2 1 3 3"}],start:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* next;\n    Node(int v, Node* n) : val(v), next(n) {}\n};\n\nNode* daoNguoc(Node* head) {\n    // prev, cur, nxt: bẻ từng mũi tên quay ngược\n    return head;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    Node* head = nullptr;\n    Node* tail = nullptr;\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        Node* q = new Node(x, nullptr);\n        if (head == nullptr) head = q; else tail->next = q;\n        tail = q;\n    }\n    head = daoNguoc(head);\n    for (Node* c = head; c != nullptr; c = c->next) cout << c->val << \" \";\n    cout << \"\\n\";\n    return 0;\n}",need:/Node\s*\*\s*daoNguoc[\s\S]*->\s*next\s*=(?!=)[\s\S]*int\s+main/,needMsg:"Hãy đảo bằng cách gán lại con trỏ next bên trong hàm daoNguoc.",py:{start:"class Node:\n    def __init__(self, val, next=None):\n        self.val = val\n        self.next = next\n\ndef daoNguoc(head):\n    # prev, cur, nxt: bẻ từng mũi tên quay ngược\n    return head\n\nn = int(input())\na = list(map(int, input().split()))\nhead = tail = None\nfor x in a:\n    q = Node(x)\n    if head is None:\n        head = q\n    else:\n        tail.next = q\n    tail = q\nhead = daoNguoc(head)\nout = []\ncur = head\nwhile cur is not None:\n    out.append(cur.val)\n    cur = cur.next\nprint(*out)",hints:["Giữ ba biến: prev (phần đã đảo), cur (nút đang xét), nxt (phần còn lại).","Trong vòng lặp: nxt = cur.next; cur.next = prev; prev = cur; cur = nxt. Python cho viết gọn: cur.next, prev, cur = prev, cur, cur.next.","Khi cur thành None, prev là head mới."],needMsg:"Hãy đảo bằng cách gán lại .next bên trong hàm daoNguoc.",need:/def\s+daoNguoc[\s\S]*\.next\s*=(?!=)/},cs:{start:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Next;\n\n    public Node(int val, Node next)\n    {\n        Val = val;\n        Next = next;\n    }\n}\n\nclass Program\n{\n    static Node DaoNguoc(Node head)\n    {\n        // prev, cur, nxt: bẻ từng mũi tên quay ngược\n        return head;\n    }\n\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]);\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        Node head = null, tail = null;\n        for (int i = 0; i < n; i++)\n        {\n            Node q = new Node(a[i], null);\n            if (head == null) head = q; else tail.Next = q;\n            tail = q;\n        }\n        head = DaoNguoc(head);\n        for (Node c = head; c != null; c = c.Next) Console.Write(c.Val + \" \");\n        Console.WriteLine();\n    }\n}",hints:["Giữ ba biến: prev (phần đã đảo), cur (nút đang xét), nxt (phần còn lại).","Trong vòng lặp: nxt = cur.Next; cur.Next = prev; prev = cur; cur = nxt.","Khi cur thành null, prev là head mới."],needMsg:"Hãy đảo bằng cách gán lại .Next bên trong hàm DaoNguoc.",need:/Node\s+DaoNguoc[\s\S]*\.Next\s*=(?!=)[\s\S]*static\s+void\s+Main/}},{t:"Xóa mọi nút có giá trị x",d:"Đầu vào: dòng 1 là n và x (1 ≤ n ≤ 10^4); dòng 2 là n số nguyên. Hãy viết hàm xoa trả về head của danh sách sau khi bỏ mọi nút có giá trị bằng x (giữ nguyên thứ tự các nút còn lại). Đầu ra: danh sách còn lại, hoặc dòng EMPTY nếu danh sách rỗng.",tests:[{in:"6 2\n1 2 3 2 2 4",out:"1 3 4"},{in:"3 5\n5 5 5",out:"EMPTY"},{in:"4 1\n1 2 3 1",out:"2 3"},{in:"1 9\n4",out:"4"},{in:"5 7\n7 1 7 7 2",out:"1 2"}],start:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* next;\n    Node(int v, Node* n) : val(v), next(n) {}\n};\n\nNode* xoa(Node* head, int x) {\n    // gợi ý: nút giả đứng trước head để nút đầu cũng có \"nút trước\"\n    return head;\n}\n\nint main() {\n    int n, x;\n    cin >> n >> x;\n    Node* head = nullptr;\n    Node* tail = nullptr;\n    for (int i = 0; i < n; i++) {\n        int v;\n        cin >> v;\n        Node* q = new Node(v, nullptr);\n        if (head == nullptr) head = q; else tail->next = q;\n        tail = q;\n    }\n    head = xoa(head, x);\n    if (head == nullptr) cout << \"EMPTY\";\n    for (Node* c = head; c != nullptr; c = c->next) cout << c->val << \" \";\n    cout << \"\\n\";\n    return 0;\n}",py:{start:"class Node:\n    def __init__(self, val, next=None):\n        self.val = val\n        self.next = next\n\ndef xoa(head, x):\n    # gợi ý: nút giả đứng trước head để nút đầu cũng có \"nút trước\"\n    return head\n\nn, x = map(int, input().split())\nhead = tail = None\nfor v in map(int, input().split()):\n    q = Node(v)\n    if head is None:\n        head = q\n    else:\n        tail.next = q\n    tail = q\nhead = xoa(head, x)\nif head is None:\n    print(\"EMPTY\")\n\nout = []\ncur = head\nwhile cur is not None:\n    out.append(cur.val)\n    cur = cur.next\nif out:\n    print(*out)",hints:["Để xóa một nút cần biến p trỏ tới nút đứng trước nó, rồi p.next = p.next.next.","Nút giả gia = Node(0, head) đứng trước head: nhờ nó, xóa nút đầu không cần trường hợp riêng. Kết quả là gia.next.","Khi vừa xóa p.next thì đừng tiến p: nút mới đứng sau p có thể cũng phải xóa."]},cs:{start:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Next;\n\n    public Node(int val, Node next)\n    {\n        Val = val;\n        Next = next;\n    }\n}\n\nclass Program\n{\n    static Node Xoa(Node head, int x)\n    {\n        // gợi ý: nút giả đứng trước head để nút đầu cũng có \"nút trước\"\n        return head;\n    }\n\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]);\n        int x = int.Parse(t[1]);\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        Node head = null, tail = null;\n        for (int i = 0; i < n; i++)\n        {\n            Node q = new Node(a[i], null);\n            if (head == null) head = q; else tail.Next = q;\n            tail = q;\n        }\n        head = Xoa(head, x);\n        if (head == null) Console.Write(\"EMPTY\");\n        for (Node c = head; c != null; c = c.Next) Console.Write(c.Val + \" \");\n        Console.WriteLine();\n    }\n}",hints:["Để xóa một nút cần biến p trỏ tới nút đứng trước nó, rồi p.Next = p.Next.Next.","Nút giả gia = new Node(0, head) đứng trước head: nhờ nó, xóa nút đầu không cần trường hợp riêng. Kết quả là gia.Next.","Khi vừa xóa p.Next thì đừng tiến p: nút mới đứng sau p có thể cũng phải xóa."]}},{t:"Độ dài chu trình",d:"Đầu vào: dòng 1 là n và k (1 ≤ n ≤ 10^4, −1 ≤ k < n); dòng 2 là n số nguyên. Chương trình mẫu dựng danh sách, rồi nếu k ≥ 0 thì nối nút cuối về nút thứ k (đánh số từ 0), tạo thành chu trình. Hãy viết hàm doDaiChuTrinh trả về số nút trên chu trình, hoặc 0 nếu không có chu trình. Không được sửa các con trỏ next.",tests:[{in:"5 2\n1 2 3 4 5",out:"3"},{in:"4 -1\n1 2 3 4",out:"0"},{in:"1 0\n9",out:"1"},{in:"3 0\n1 2 3",out:"3"},{in:"6 5\n1 2 3 4 5 6",out:"1"},{in:"6 -1\n1 1 1 1 1 1",out:"0"}],start:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* next;\n    Node(int v, Node* n) : val(v), next(n) {}\n};\n\nint doDaiChuTrinh(Node* head) {\n    // con trỏ nhanh đi 2 bước, chậm đi 1 bước: gặp nhau thì có chu trình\n    return 0;\n}\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    Node* head = nullptr;\n    Node* tail = nullptr;\n    Node* noi = nullptr;\n    for (int i = 0; i < n; i++) {\n        int v;\n        cin >> v;\n        Node* q = new Node(v, nullptr);\n        if (head == nullptr) head = q; else tail->next = q;\n        tail = q;\n        if (i == k) noi = q;\n    }\n    tail->next = noi;     // k = -1 thì noi = nullptr: không có chu trình\n    cout << doDaiChuTrinh(head) << \"\\n\";\n    return 0;\n}",py:{start:"class Node:\n    def __init__(self, val, next=None):\n        self.val = val\n        self.next = next\n\ndef doDaiChuTrinh(head):\n    # con trỏ nhanh đi 2 bước, chậm đi 1 bước: gặp nhau thì có chu trình\n    return 0\n\nn, k = map(int, input().split())\nhead = tail = noi = None\nfor i, v in enumerate(map(int, input().split())):\n    q = Node(v)\n    if head is None:\n        head = q\n    else:\n        tail.next = q\n    tail = q\n    if i == k:\n        noi = q\ntail.next = noi      # k = -1 thì noi là None: không có chu trình\nprint(doDaiChuTrinh(head))",hints:["Thuật toán Floyd: cham đi 1 bước, nhanh đi 2 bước. Nhanh gặp None thì không có chu trình; cham is nhanh thì có.","Khi đã gặp nhau, cả hai đang ở trong chu trình: giữ cham đứng yên, cho một biến đi vòng tới khi quay lại cham, đếm số bước.","Dùng is để so sánh hai nút (cùng một đối tượng), không so sánh val: các nút khác nhau có thể cùng giá trị."]},cs:{start:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Next;\n\n    public Node(int val, Node next)\n    {\n        Val = val;\n        Next = next;\n    }\n}\n\nclass Program\n{\n    static int DoDaiChuTrinh(Node head)\n    {\n        // con trỏ nhanh đi 2 bước, chậm đi 1 bước: gặp nhau thì có chu trình\n        return 0;\n    }\n\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]);\n        int k = int.Parse(t[1]);\n        Node noi = null;\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        Node head = null, tail = null;\n        for (int i = 0; i < n; i++)\n        {\n            Node q = new Node(a[i], null);\n            if (head == null) head = q; else tail.Next = q;\n            tail = q;\n            if (i == k) noi = q;\n        }\n        tail.Next = noi;     // k = -1 thì noi là null: không có chu trình\n        Console.WriteLine(DoDaiChuTrinh(head));\n    }\n}",hints:["Thuật toán Floyd: cham đi 1 bước, nhanh đi 2 bước. Nhanh gặp null thì không có chu trình; cham == nhanh thì có.","Khi đã gặp nhau, cả hai đang ở trong chu trình: giữ cham đứng yên, cho một biến đi vòng tới khi quay lại cham, đếm số bước.","Với lớp tự viết, == so sánh hai biến có trỏ tới cùng một đối tượng không, không so sánh Val."]}}]);

